import { CurrencyPipe } from '@angular/common';
import { Component, inject, OnInit, signal } from '@angular/core';

import { PagedResult, ProductListItem } from '../../../core/models/product.model';
import { ProductService } from '../../../core/services/product.service';

@Component({
  selector: 'app-product-list',
  imports: [CurrencyPipe],
  templateUrl: './product-list.html',
  styleUrl: './product-list.scss'
})
export class ProductList implements OnInit {
  private readonly productService = inject(ProductService);

  readonly page = signal(1);
  readonly result = signal<PagedResult<ProductListItem> | null>(null);
  readonly error = signal(false);

  private latestRequestedPage = 0;

  ngOnInit(): void {
    this.loadPage(1);
  }

  loadPage(page: number): void {
    this.page.set(page);
    this.error.set(false);
    this.latestRequestedPage = page;

    this.productService.getProducts(page).subscribe({
      next: (result) => {
        if (this.latestRequestedPage === page) {
          this.result.set(result);
        }
      },
      error: () => {
        if (this.latestRequestedPage === page) {
          this.error.set(true);
        }
      }
    });
  }
}

@if (error()) {
  <p class="product-list__error">Die Produktliste konnte nicht geladen werden.</p>
} @else if (result(); as r) {
  <ul class="product-list">
    @for (item of r.items; track item.id) {
      <li class="product-list__item">
        <span class="product-list__name">{{ item.name }}</span>
        <span class="product-list__subcategory">{{ item.subcategoryName }}</span>
        <span class="product-list__price">{{ item.minPrice | currency: 'EUR' }}</span>
      </li>
    }
  </ul>

  <nav class="product-list__pagination">
    <button type="button" [disabled]="page() <= 1" (click)="loadPage(page() - 1)">Vorherige</button>
    <span>Seite {{ page() }} von {{ r.totalPages }}</span>
    <button type="button" [disabled]="page() >= r.totalPages" (click)="loadPage(page() + 1)">Nächste</button>
  </nav>
}

